RESULT_FILE = Path("aig_student_results.json")
if not RESULT_FILE.exists(): RESULT_FILE.write_text("[]", encoding="utf-8")

def load_results():
    try: return json.loads(RESULT_FILE.read_text(encoding="utf-8"))
    except: return []

def save_result(row):
    rows = load_results(); rows.append(row)
    RESULT_FILE.write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding="utf-8")

def update_student_record(state, **changes):
    """Оқушы кірген сәттен бастап бір сессияның анализін жаңартып отырады."""
    if not state or not state.get("session_id"): return
    rows=load_results(); sid=state["session_id"]
    record=next((r for r in rows if r.get("ID")==sid),None)
    if record is None:
        record={"ID":sid,"Кіру уақыты":state.get("login_time",datetime.now().strftime("%d.%m.%Y %H:%M")),
                "Соңғы белсенділік":"","Оқушы":state.get("name",""),
                "Сынып":f"{state.get('grade','')} «{state.get('letter','')}»",
                "Тақырып":state.get("topic",""),"Кезең":"Профиль сақталды","Орындалған":"0",
                "Бастапқы":None,"Жеке оқу":None,"PISA":None,"Қорытынды":None,
                "Өсу":None,"Деңгей":"Анықталмады","Қиындық":"","Соңғы жауап":"","Жауап статусы":""}
        rows.append(record)
    record.update(changes); record["Соңғы белсенділік"]=datetime.now().strftime("%d.%m.%Y %H:%M:%S")
    RESULT_FILE.write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding="utf-8")

def task_visual_html(task, topic=""):
    """SVG is built from the CURRENT task text; labels come from that task, not from a generic unrelated picture."""
    import html as _html
    q=str(task.get("q","")).lower(); skill=str(task.get("skill","")).lower(); own=q+" "+skill
    nums=re.findall(r"(?<!\w)\d+(?:[,.]\d+)?",q)
    esc=lambda x:_html.escape(str(x))
    triangle=any(k in own for k in ["үшбұрыш","треуголь","гипотенуз","катет","пифагор","шатыр","бағана","сым"])
    circle=any(k in own for k in ["шеңбер","дөңгелек","окруж","радиус","диаметр"])
    rectangle=any(k in own for k in ["тіктөртбұрыш","тік төртбұрыш","прямоуголь","шаршы","квадрат пішінді","бөлме","еден","саябақ"])
    graph=any(k in own for k in ["координат","график","функция","парабола"])
    if triangle:
        # labels reflect task values: roof/base-side, pole/wire, base-height, Pythagoras.
        a=nums[0] if len(nums)>0 else "a"; b=nums[1] if len(nums)>1 else "h"
        if any(k in q for k in ["сым","гипотенуз"]): hyp,base=a,b; left="h"; right=hyp; bottom=base
        elif "шатыр" in q or "теңбүйір" in q: bottom=a; right=b; left=b
        else: bottom=a; left="h="+b if len(nums)>1 else "h"; right=""
        return f"""<div class='task-visual'><h3>👁️ Дәл осы есептің кескіні</h3><svg viewBox='0 0 560 270'><polygon points='75,220 485,220 280,45' fill='#e0f2fe' stroke='#4338ca' stroke-width='6'/><line x1='280' y1='45' x2='280' y2='220' stroke='#ef4444' stroke-width='4' stroke-dasharray='9 7'/><path d='M280 200h20v20' fill='none' stroke='#ef4444' stroke-width='4'/><text x='245' y='250' font-size='20'>табан: {esc(bottom)} м</text><text x='292' y='140' font-size='20'>{esc(left)}</text><text x='385' y='125' font-size='20'>{esc(right)}</text></svg><p>{esc(task.get('context',''))}</p></div>"""
    if circle:
        r=nums[0] if nums else "r"
        return f"""<div class='task-visual'><h3>👁️ Дәл осы есептің кескіні</h3><svg viewBox='0 0 560 260'><circle cx='280' cy='130' r='92' fill='#fce7f3' stroke='#be185d' stroke-width='6'/><line x1='280' y1='130' x2='372' y2='130' stroke='#4338ca' stroke-width='5'/><circle cx='280' cy='130' r='6'/><text x='315' y='115' font-size='20'>r={esc(r)}</text></svg></div>"""
    if rectangle:
        a=nums[0] if len(nums)>0 else "a"; b=nums[1] if len(nums)>1 else "b"
        return f"""<div class='task-visual'><h3>👁️ Дәл осы есептің кескіні</h3><svg viewBox='0 0 560 260'><rect x='85' y='45' width='390' height='155' fill='#cffafe' stroke='#0369a1' stroke-width='6'/><text x='235' y='235' font-size='20'>{esc(a)}</text><text x='45' y='130' font-size='20'>{esc(b)}</text><line x1='85' y1='215' x2='475' y2='215' stroke='#7c3aed' stroke-width='3'/></svg></div>"""
    if graph:
        return """<div class='task-visual'><h3>👁️ Осы тапсырмаға арналған координаталық кескін</h3><svg viewBox='0 0 560 290'><line x1='35' y1='220' x2='530' y2='220' stroke='#172554' stroke-width='3'/><line x1='280' y1='25' x2='280' y2='270' stroke='#172554' stroke-width='3'/><text x='510' y='247'>x</text><text x='295' y='40'>y</text></svg><p>Нақты функция тапсырма мәтінінде берілген; осьтер сол модельді салуға арналған.</p></div>"""
    return ""

def task_card_html(task, number, total, kind="Тапсырма", topic="", language="Қазақша"):
    shown=localize_task(task,language)
    shown_kind=to_russian(kind) if language=="Русский" else kind
    lang="ru" if language=="Русский" else "kk"
    return f"<div class='task notranslate' translate='no' lang='{lang}'><span>{shown_kind} · {number} / {total}</span><h2>{shown.get('q','')}</h2><small>{shown.get('objective','')}</small></div>"

def clean_answer(v):
    """Unicode/keyboard-safe normalization for school mathematics answers."""
    s=str(v or "").lower().strip()
    # common keyboard and Unicode variants
    repl={"−":"-","–":"-","—":"-","×":"*","·":"*","∙":"*","⋅":"*","÷":"/","∶":":",
          "sqrt":"√","түбір":"√","корень":"√","π":"pi","^2":"²","**2":"²","^3":"³","**3":"³",
          "⁰":"0","¹":"1","⁴":"4","⁵":"5","⁶":"6","⁷":"7","⁸":"8","⁹":"9",
          "[":"(","]":")","{":"(","}":")","：":":","；":";"}
    for a,b in repl.items(): s=s.replace(a,b)
    s=s.replace("х","x")  # Cyrillic х -> Latin x in formulas
    s=re.sub(r"\s+","",s)
    s=re.sub(r"x[₁1]\s*=", "", s); s=re.sub(r"x[₂2]\s*=", "", s)
    return s

def strip_optional_units(value):
    s=clean_answer(value)
    suffixes=(r"°c",r"°с",r"°",r"градус(?:а|ов)?",r"град",r"теңге",r"тг",r"км/сағ",r"км/ч",r"м/с",
              r"км²",r"м²",r"см²",r"мм²",r"км³",r"м³",r"см³",r"км3",r"м3",r"см3",r"км",r"см",r"мм",r"м",
              r"кг",r"г",r"л",r"сағат",r"час(?:а|ов)?",r"минут",r"мин",r"секунд",r"сек",r"%")
    changed=True
    while changed:
        old=s
        for u in suffixes: s=re.sub(u+r"$","",s)
        changed=(old!=s)
    return s

def _numeric_value(v):
    s=strip_optional_units(v).replace(",",".")
    try:
        if re.fullmatch(r"[-+]?\d+(?:\.\d+)?",s): return float(s)
        if re.fullmatch(r"[-+]?\d+\s*/\s*\d+",s):
            a,b=s.split("/"); return float(a)/float(b)
    except: pass
    return None

def _sympy_expr(value, expected_hint=""):
    s=clean_answer(value); hint=clean_answer(expected_hint)
    # Unicode powers and phone-friendly x2/x3 when expected contains powers.
    if "²" in hint: s=re.sub(r"([a-z])2(?!\d)",r"\1**2",s)
    if "³" in hint: s=re.sub(r"([a-z])3(?!\d)",r"\1**3",s)
    s=s.replace("²","**2").replace("³","**3").replace(",",".")
    # roots: √9, √x, √(x+1)
    s=re.sub(r"√\s*\(([^()]*)\)",r"sqrt(\1)",s)
    s=re.sub(r"√\s*([a-z0-9.]+)",r"sqrt(\1)",s)
    # colon is often division in typed math
    if ":" in s and ";" not in s: s=s.replace(":","/")
    try:
        from sympy.parsing.sympy_parser import parse_expr, standard_transformations, implicit_multiplication_application, convert_xor
        trans=standard_transformations+(implicit_multiplication_application,convert_xor)
        local={k:sp.Symbol(k) for k in "xyabctmnpq"}
        local.update({"sqrt":sp.sqrt,"sin":sp.sin,"cos":sp.cos,"tan":sp.tan,"log":sp.log,"pi":sp.pi})
        if "=" in s:
            l,r=s.split("=",1); return sp.simplify(parse_expr(l,local_dict=local,transformations=trans)-parse_expr(r,local_dict=local,transformations=trans))
        return sp.simplify(parse_expr(s,local_dict=local,transformations=trans))
    except Exception:
        return None

def math_variants(value, expected_hint=""):
    b=clean_answer(value); h=clean_answer(expected_hint); out={b,b.replace("*","")}
    if "²" in h: out.add(re.sub(r"([a-z])2(?!\d)",r"\1²",b))
    if "³" in h: out.add(re.sub(r"([a-z])3(?!\d)",r"\1³",b))
    return out

def sympy_form(value, expected_hint=""):
    return _sympy_expr(value,expected_hint)

def answer_is_correct(student, expected):
    """Accept mathematically equivalent answers despite keyboard/symbol variants."""
    if student is None or not str(student).strip(): return False
    s,e=clean_answer(student),clean_answer(expected)
    if s==e: return True
    su,eu=strip_optional_units(student),strip_optional_units(expected)
    if su==eu and su: return True
    # numeric equality: 0.5 == 1/2, comma == dot, optional units
    sn,en=_numeric_value(student),_numeric_value(expected)
    if sn is not None and en is not None and abs(sn-en)<=1e-9*max(1,abs(en)): return True
    # unordered multiple roots/answers: 2;3 == 3;2, x=2 немесе x=3
    def parts(v):
        z=clean_answer(v).replace("немесе",";").replace("или",";").replace("x=","")
        if ";" not in z: return None
        ps=[p for p in z.split(";") if p]
        vals=[]
        for p in ps:
            n=_numeric_value(p); vals.append(("n",round(n,10)) if n is not None else ("s",p))
        return sorted(vals,key=str)
    if parts(student) is not None and parts(student)==parts(expected): return True
    if math_variants(student,expected)&math_variants(expected,expected): return True
    # symbolic equivalence: implicit multiplication, roots, powers, expanded/factored forms
    sf,ef=_sympy_expr(student,expected),_sympy_expr(expected,expected)
    if sf is not None and ef is not None:
        try:
            # for equations, non-zero scalar multiples define the same equation
            if "=" in s and "=" in e:
                if sp.simplify(sf-ef)==0: return True
                if ef!=0:
                    ratio=sp.simplify(sf/ef)
                    if not getattr(ratio,"free_symbols",set()) and ratio!=0: return True
            elif sp.simplify(sf-ef)==0: return True
        except Exception: pass
    return False

def score_level(score):
    if score < 40: return "Бастапқы", "🌱", "Негізгі ұғым мен үлгі бойынша жұмыс қажет"
    if score < 70: return "Базалық", "🌿", "Ережені қолдану мен екі қадамдық есепті бекіту қажет"
    if score < 90: return "Жеткілікті", "⭐", "Талдау және функционалдық тапсырмаларға көшуге болады"
    if score < 100: return "Жоғары", "🏆", "Күрделі модельдеу және зерттеу тапсырмалары ұсынылады"
    return "Шебер", "🚀", "Диагностика толық орындалды: олимпиадалық және зерттеу есептері ұсынылады"

def ai_text(prompt, image=None):
    if not GEMINI_API_KEY: return None
    try:
        import google.generativeai as genai
        genai.configure(api_key=GEMINI_API_KEY)
        model = genai.GenerativeModel("gemini-1.5-flash")
        response = model.generate_content([prompt, image] if image is not None else prompt)
        return response.text
    except Exception as e:
        return None

RU_CACHE={}
def to_russian(text):
    """Математикалық таңбаларды өзгертпей қазақша оқу мәтінін орысшаға аударады."""
    if not text: return text
    key=hashlib.sha1(str(text).encode()).hexdigest()
    if key in RU_CACHE: return RU_CACHE[key]
    prompt=f"""Переведи следующий учебный математический текст с казахского на русский язык.
Сохрани Markdown, HTML-теги, числа и математические символы x², √, π, ∫, log, sin, cos без изменений.
Пиши естественно и понятно для школьника 5–11 класса. Верни только перевод.

ТЕКСТ:
{text}"""
    result=ai_text(prompt)
    if not result:
        # Офлайн резерв: негізгі интерфейс сөздері; формулалар мен сандар өзгермейді.
        result=str(text)
        replacements=[
          ("Тапсырма","Задание"),("Бастапқы диагностика","Входная диагностика"),("Қорытынды диагностика","Итоговая диагностика"),
          ("Жеке тапсырма","Индивидуальное задание"),("Есептің кескіні","Схема задачи"),("Графиктік кескін","Графическое представление"),
          ("мәнін тап","найди значение"),("теңдеуін шеш","реши уравнение"),("ықшамда","упрости"),("анықта","определи"),
          ("ауданын тап","найди площадь"),("периметрін тап","найди периметр"),("бұрышын тап","найди угол"),
          ("Жауабы","Ответ"),("Толық шығарылуы","Полное решение"),("Теория","Теория"),("Қадам","Шаг"),
          ("Дұрыс","Верно"),("Қате","Ошибка"),("Бағыт","Подсказка"),("Сынып","Класс"),("Тақырып","Тема")]
        for kz,ru in replacements: result=result.replace(kz,ru).replace(kz.lower(),ru.lower())
    RU_CACHE[key]=result
    return result

def localize_task(task, language):
    if language!="Русский": return dict(task)
    out=dict(task)
    for field in ["q","hint","skill","objective","explain","context"]:
        if out.get(field): out[field]=to_russian(out[field])
    return out

def localize_tasks(tasks, language):
    return [localize_task(t,language) for t in tasks]

def extract_json(text):
    if not text: return None
    try:
        text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.M).strip()
        start, end = text.find("["), text.rfind("]")
        return json.loads(text[start:end+1])
    except: return None

def resolved_topic(choice, custom):
    choice=RU_TO_KZ.get(choice,choice)
    return custom.strip() if choice == "Басқа тақырып" and custom.strip() else choice

def demo_tasks(grade, topic, phase="initial"):
    n = int(grade)
    offset = 2 if phase == "final" else 0
    if "Көпмүше" in topic:
        base = [
            ("3x + 2x өрнегін ықшамда.", "5x", "Ұқсас мүшелердің коэффициенттерін салыстыр.", "Ұқсас мүшелер"),
            ("(2x+3)+(x−5) өрнегін ықшамда.", "3x-2", "Жақшаны ашып, x-тері бар және бос мүшелерді бөлек біріктір.", "Көпмүшелерді қосу"),
            ("2x(3x−4) өрнегін аш.", "6x²-8x", "2x-ті жақшадағы әр мүшеге көбейт.", "Көбейту")
        ]
    elif "түбір" in topic.lower():
        base = [
            ("√49 мәнін тап.", "7", "Квадраты 49 болатын оң санды ойла.", "Түбір анықтамасы"),
            ("√50 өрнегін ықшамда.", "5√2", "50 санынан толық квадрат көбейткішті бөл.", "Түбірді ықшамдау"),
            ("3√2+5√2 өрнегін ықшамда.", "8√2", "Бірдей түбірлері бар мүшелердің коэффициенттерін қос.", "Иррационал өрнек")
        ]
    else:
        base = [
            (f"{n+offset}+{2*n} мәнін тап.", str(3*n+offset), "Қосу амалын мұқият орында.", topic),
            (f"{3*n+offset}−{n} мәнін тап.", str(2*n+offset), "Азайғыш пен азайтқышты дұрыс анықта.", topic),
            (f"{n} оқушының әрқайсысына 3 дәптерден берілді. Барлығы неше дәптер?", str(3*n), "Бірдей топтар санын көбейту амалымен байланыстыр.", "Функционалдық сауаттылық")
        ]
    return [{"q":q,"a":a,"hint":h,"skill":s,"objective":f"{grade}-сынып: {topic}","explain":f"Бағыт: {h}"} for q,a,h,s in base]

def _practice_task(q, a, h, s, topic, route="Жеке оқу"):
    return {"q":q,"a":a,"hint":h,"skill":s,"objective":f"{route} · {topic}","explain":f"Қадамдық бағыт: {h}"}

def _task_key(task):
    return re.sub(r"\s+", "", str(task.get("q", "")).lower())

def _skill_relevance(task, weak_skills):
    """Қате кеткен дағдыға мазмұндық жақындығын есептейді."""
    text=(str(task.get("skill", ""))+" "+str(task.get("q", ""))).lower()
    words=set(re.findall(r"[а-яәіңғүұқөһa-z]{4,}", str(weak_skills).lower()))
    return sum(1 for word in words if word in text)

def adaptive_fallback(grade, topic, level_name, weak_skills="", diagnostic_answers=None, score=None):
    """5 жеке тапсырманы ұпай мен нақты қате дағдыларға қарай таңдайды."""
    raw = PRACTICE_RAW.get(topic)
    practice = ([_practice_task(q,a,h,s,topic) for q,a,h,s in raw] if raw else [])
    diagnostic_answers=diagnostic_answers or []
    diagnostic_questions={_task_key(x) for x in diagnostic_answers if x.get("q")}
    curated=[x for x in (curated_tasks(grade, topic) or []) if _task_key(x) not in diagnostic_questions]
    pisa=pisa_tasks_for_topic(grade, topic, level_name)
    olympiad = OLYMPIAD_RAW.get(topic, [])
    olympiad_tasks = [_practice_task(q,a,h,s,topic,"Олимпиадалық бағыт") for q,a,h,s in olympiad]
    master_raw=MASTER_PRACTICE_RAW.get(topic,[])
    master_tasks=[_practice_task(q,a,h,s,topic,"Шеберлік деңгейі") for q,a,h,s in master_raw]
    # Арнайы қор жоқ тақырыпта да шеберге жай есеп берілмейді: екі тексерілген
    # дағдыны бір зерттеу тапсырмасына біріктіреміз.
    if not master_tasks:
        source=practice+pisa+curated
        for j in range(min(5,len(source))):
            a=source[j%len(source)]; b=source[(j+2)%len(source)]
            master_tasks.append({
                "q":f"Кешенді тапсырма. A) {a['q']}  B) {b['q']} Екі нәтижені де негізде.",
                "a":f"{a['a']};{b['a']}",
                "hint":f"A бөлігі: {a.get('hint','')} B бөлігі: {b.get('hint','')}",
                "skill":f"{a.get('skill','')} + {b.get('skill','')}",
                "objective":f"Шеберлік деңгейі · {topic}",
                "explain":f"Алдымен A және B бөліктерін бөлек шеш, кейін қолданылған екі әдісті салыстыр. A: {a.get('explain',a.get('hint',''))} B: {b.get('explain',b.get('hint',''))}"
            })

    # Бірдей сұрақты қайталамайтын қор құру.
    pool=[]; seen=set()
    def add_many(items):
        for item in items:
            key=_task_key(item)
            if key and key not in seen:
                seen.add(key); pool.append(item)

    if score == 100 or level_name == "Шебер":
        # 100%: кәдімгі практика қайталанбайды; арнайы күрделі қор бірінші беріледі.
        add_many(master_tasks)
        add_many(olympiad_tasks)
        add_many(list(reversed(pisa)))
    else:
        # Әр деңгейге бөлек мазмұндық қор беріледі; тек орындары ауыспайды.
        if level_name == "Бастапқы":
            candidates=practice[:3]+pisa[:2]+curated[:2]+demo_tasks(grade,topic)
        elif level_name == "Базалық":
            candidates=practice[1:]+pisa[:3]+curated[2:]+demo_tasks(grade,topic)[1:]
        elif level_name == "Жеткілікті":
            candidates=practice[2:]+pisa+olympiad_tasks+list(reversed(curated))
        else:
            candidates=olympiad_tasks+list(reversed(pisa))+list(reversed(practice))+list(reversed(curated))
        # Таңдалған деңгей қорының ішінде қате кеткен нақты дағды бірінші оқытылады.
        ranked=sorted(enumerate(candidates),key=lambda pair:(-_skill_relevance(pair[1],weak_skills),pair[0]))
        add_many([item for _,item in ranked])

    # Сирек тақырыпта қор аз болса да, 5 тексерілген тапсырмаға дейін толықтыру.
    add_many(practice); add_many(curated); add_many(pisa); add_many(demo_tasks(grade,topic))
    return pool[:5]

def generate_tasks(grade, topic, phase, count=5, level="Базалық"):
    # Бағаланатын тапсырмалардың жауабын ЖИ-ға құрғызбаймыз.
    # Барлық диагностика тек қолмен тексерілген тұрақты банктен алынады.
    if "қорытынды" in str(phase).lower():
        final=final_tasks(grade,topic)
        if final: return final[:count]
    curated = curated_tasks(grade, topic)
    if curated: return curated[:count]
    return demo_tasks(grade, topic, "final" if phase == "қорытынды" else "initial")[:count]



