def formula_markdown(grade, query=""):
    grade=str(grade or "7")
    q=str(query or "").strip().lower()
    # Тақырып жазылса, тек таңдалған сыныптан емес, 5–11-сыныптың барлық
    # формуласынан іздейміз. Сондықтан «квадрат теңдеу» 7-сынып карточкасы
    # таңдалып тұрса да бірден табылады.
    grade_items=[(grade,FORMULA_LIBRARY.get(grade,{}))] if not q else list(FORMULA_LIBRARY.items())
    title=f"# 📐 {grade}-сынып формулалары" if not q else f"# 🔎 «{query}» бойынша формулалар"
    out=[title, "Бұл анықтамалық — **оқыту және қайталау** үшін. Формуланы жаттап қана қоймай, қай кезде қолданылатынын түсінуге тырыс."]
    found=0
    aliases={"квадрат теңдеуі":"квадрат теңдеу","үшбұрыш":"үшбұрыштар",
             "процент":"пайыз","дробь":"бөлшек","производная":"туынды"}
    q2=aliases.get(q,q)
    words=[w for w in re.findall(r"[а-яәіңғүұқөһa-z0-9]+",q2) if len(w)>2]
    for g,data in grade_items:
        for section, formulas in data.items():
            joined=(section+" "+" ".join(formulas)).lower()
            tokens=re.findall(r"[а-яәіңғүұқөһa-z0-9]+",joined)
            match=(not q) or (q2 in joined) or (words and all(any(w in token or token in w for token in tokens) for w in words))
            if not match: continue
            found+=1; out.append(f"\n## ✨ {g}-сынып · {section}")
            for i,f in enumerate(formulas,1):
                out.append(f"<div class='formula-chip'><span>{i}</span><code>{f}</code></div>")
    if not found:
        out.append("\nІздеу бойынша формула табылмады. Тақырыпты қысқаша жазыңыз: мысалы, **комбинаторика**, **квадрат теңдеу**, **туынды**, **пайыз**.")
    out.append("\n> 💡 Кеңес: есеп шығарғанда алдымен **берілгені → ізделінді → формула → мәндерді қою → есептеу → тексеру** ретін ұстан.")
    return "\n".join(out)

def formula_for_topic(grade, topic):
    """Көмекшіге тақырыпқа сәйкес формулаларды береді."""
    g=FORMULA_LIBRARY.get(str(grade),{})
    t=str(topic or "").lower()
    scored=[]
    keys={"комбин":"комбинатор", "ықтимал":"ықтимал", "квадрат":"квадрат", "түбір":"түбір", "тригоном":"тригоном", "прогресс":"прогресс", "туынды":"туынды", "интеграл":"интеграл", "логариф":"логариф", "пайыз":"пайыз", "пропор":"пропор", "геометр":"геометр", "дәреже":"дәреже", "функц":"функц"}
    for section, fs in g.items():
        hay=(section+" "+" ".join(fs)).lower(); score=0
        for a,b in keys.items():
            if a in t and b in hay: score+=3
        for w in re.findall(r"[а-яәіңғүұқөһa-z]+",t):
            if len(w)>=5 and w in hay: score+=1
        if score: scored.append((score,section,fs))
    if not scored: return "", []
    scored.sort(reverse=True,key=lambda x:x[0]); _,section,fs=scored[0]
    return section,fs

def formula_for_current_task(task, grade, profile_topic):
    """Экрандағы нақты есепке қажет формуланы таңдайды.
    PISA есебі профиль тақырыбынан бөлек контексте болса, қатысы жоқ формула көрсетілмейді.
    """
    q=str((task or {}).get("q","")).lower()
    skill=str((task or {}).get("skill","")).lower()
    text=q+" "+skill
    rules=[
        (("билет","автобус","әр оқушы"), "Шығынды бөлу", ["Жалпы шығын = билет шығыны + автобус құны", "Билет шығыны = оқушы саны × бір билет бағасы", "Бір оқушының үлесі = жалпы шығын ÷ оқушы саны"]),
        (("жеңілдік","соңғы төлем"), "Кезеңдік пайыз", ["Жеңілдеген баға = бастапқы баға × (1 − p/100)", "Әр жеңілдік алдыңғы шыққан бағаға жеке қолданылады"]),
        (("бюджет","3/8","0,25"), "Бөлшек және бюджет", ["Жұмсалған сома = жалпы сома × жұмсалған үлес", "Қалған сома = жалпы сома × (1 − барлық жұмсалған үлес)"]),
        (("су","үнем"), "Пайыздық үнем", ["Бір күндік үнем = бастапқы шығын × p/100", "Жалпы үнем = бір күндік үнем × күн саны"]),
        (("карта","масштаб"), "Масштаб және қозғалыс", ["Нақты қашықтық = картадағы қашықтық × масштаб саны", "Уақыт = қашықтық ÷ жылдамдық"]),
        (("қатынас","сусын"), "Қатынас", ["Бір үлес = жалпы көлем ÷ үлестер қосындысы", "Керек бөлік = бір үлес × қажетті үлес саны"]),
        (("еден","қап"), "Масштаб және аудан", ["S = a × b", "Материал мөлшері = аудан × 1 м²-ге кететін мөлшер", "Толық қап саны жоғары қарай дөңгелектенеді"]),
        (("такси","тариф"), "Сызықтық модель", ["Тариф құны = бастапқы төлем + 1 км бағасы × қашықтық", "Бағалары тең болғанда екі өрнекті теңестіреміз"]),
        (("бақ","ұзындығы","енінен"), "Квадрат модель", ["S = a × b", "Ені x болса, ұзындығы x + d", "x(x+d)=S"]),
        (("қосымша гб","айлық төлем"), "Теңсіздік", ["Жалпы төлем = тұрақты төлем + бірлік бағасы × саны", "Жалпы төлем ≤ бюджет"]),
        (("велосипед","жалдау"), "Функцияны қолдану", ["Жалпы төлем = бастапқы төлем + сағаттық төлем × уақыт", "Уақыт = (бюджет − бастапқы төлем) ÷ сағаттық төлем"]),
        (("доп","ең жоғары"), "Парабола төбесі", ["t₀ = −b/(2a)"]),
        (("қуат","әр келесі сағат"), "Арифметикалық прогрессия", ["aₙ = a₁ + (n−1)d", "Sₙ = n(a₁+aₙ)/2"]),
        (("қарама-қарсы бұрыш","төте жол"), "Пифагор теоремасы", ["d = √(a²+b²)"]),
        (("дөңгелек","бояу"), "Шеңбер ауданы", ["S = πr²", "Бояу мөлшері = аудан × 1 м²-ге кететін бояу"]),
        (("пандус","көлбеу"), "Пифагор теоремасы", ["l = √(a²+b²)"]),
        (("орташа","кешігу"), "Арифметикалық орта", ["Орташа мән = барлық мәндердің қосындысы ÷ мәндер саны"]),
        (("ақаулы","жиілік"), "Пропорциялық болжам", ["Ақау үлесі = ақаулы саны ÷ барлық өнім саны", "Болжамды саны = жаңа көлем × ақау үлесі"]),
        (("электр көлігі","ықтимал"), "Қайтарусыз таңдау ықтималдығы", ["P = бірінші қолайлы ықтималдық × екінші қолайлы ықтималдық"]),
        (("файл","2 есе"), "Көрсеткіштік модель", ["Соңғы көлем = бастапқы көлем × 2ⁿ"]),
        (("дыбыс","log"), "Логарифмдік модель", ["L = 10log₁₀(I/I₀)"]),
        (("бактерия","екі еселен"), "Көрсеткіштік өсу", ["N = N₀ × 2ⁿ", "n = жалпы уақыт ÷ бір кезең уақыты"]),
        (("қорап","1/8"), "Бөлшек", ["Барлық өнім = қорап саны × бір қораптағы өнім", "Қалғаны = барлық өнім × (1 − алынған үлес)"]),
        (("40%","қалған жұмыс"), "Пайыз және уақыт", ["Қалған үлес = 100% − орындалған пайыз", "Қалған уақыт = толық уақыт × қалған үлес"]),
    ]
    for needles,section,formulas in rules:
        if all(x in text for x in needles): return section,formulas
    # Нақты есепке арнайы ереже табылмаса, оның дағдысын профиль тақырыбынан жоғары қоямыз.
    task_topic=(task or {}).get("skill") or (task or {}).get("objective") or profile_topic
    return formula_for_topic(grade,task_topic)

def learning_visual_markdown(topic):
    t=str(topic or "").lower()
    if any(k in t for k in ["пифагор","үшбұрыш","треуголь"]):
        return """\n### 👁️ Кескін\n```text\n        C\n       /|\\\n      / | \\\n   a /  |h \\ b\n    /___|___\\\n   A    c    B\n```\nКескінде қабырғаларды шарттағы шамалармен сәйкестендіріп белгіле."""
    if any(k in t for k in ["функц","парабол","график"]):
        return """\n### 👁️ Кескінді елестету\n```text\n y\n ↑       •\n |     •   •\n |   •       •\n +────────────→ x\n```\nГрафикте x өзгергенде y қалай өзгеретінін нүктелер арқылы бақыла."""
    if any(k in t for k in ["шеңбер","окруж","дөңгелек"]):
        return """\n### 👁️ Кескін\n```text\n      .-oooo-.\n    .'   O----A\n   /      r    \\\n   \\           /\n    '.       .'\n      '-...-'\n```\nOA = r — радиус, диаметр d = 2r."""
    return ""

def generate_learning(grade, topic, level_name, weak, diagnostic_answers=None, score=None):
    f_section, f_list = formula_for_topic(grade, topic)
    formula_context = "\n".join(f_list) if f_list else "Тақырыпқа сәйкес негізгі формуланы өзің анықтап, дұрыс математикалық түрде жаз."
    route_note = ("Оқушы 100% алды. Қайталау емес, күрделі дәлелдеу, бірнеше тәсіл, параметр және олимпиадалық идеяларды түсіндір."
                  if score == 100 else f"Қате кеткен дағдыларды бірінші кезекте түзет: {weak}. Әр әлсіз дағдыға жеке шағын түсіндіру бер.")
    prompt = f"""{grade}-сыныптың «{topic}» тақырыбы. Диагностика нәтижесі: {score}%. Оқушы деңгейі: {level_name}. Әлсіз дағдысы: {weak}.
Бұл — БАҒАЛАУ ЕМЕС, ЖЕКЕ ОҚЫТУ БӨЛІМІ. Сондықтан ештеңені жасырма: оқушыға тақырыпты барынша ашық әрі толық үйрет.
Жеке маршрут: {route_note}
Қазақстан оқу бағдарламасына сай: оқу мақсаты, негізгі ұғымдар, барлық қажет ереже/формула, формуладағы әр таңбаның мағынасы және қолдану шарты, кемінде 2 толық шешілген мысал, жиі қате, өзін-өзі тексеру тәсілі, есте сақтау кеңесін бер.
Осы тақырыпқа сәйкес анықтамалық формулалар:
{formula_context}
Әр мысалды «Берілгені → Формула → 1-қадам → 2-қадам → ... → Жауап → Тексеру» ретімен толық шығар. Неліктен әр амал жасалғанын түсіндір.
Кескін/график/сызба қажет тақырып болса, қарапайым мәтіндік (ASCII) кескін қосып, ондағы белгілерді түсіндір.
Қазақша, Markdown форматында, жасына сай анық жаз. Формулаларды жеке жолға дұрыс математикалық таңбалармен көрсет."""
    theory = ai_text(prompt)
    if not theory:
        specific = THEORY_GUIDES.get(topic, "")
        theory = f"""### {topic}: жеке теория
**Деңгей:** {level_name}
**Назар аударатын дағды:** {weak}

{specific}

**Негізгі формулалар:**
{chr(10).join('- **'+x+'**' for x in f_list) if f_list else '- Тақырып шартына сәйкес ережені таңда.'}

**Формуланы түсіну тәртібі:**
- Формуланың сол жағы — табылатын немесе түрлендірілетін шама.
- Оң жағындағы әр әріп есеп шартындағы нақты мәнмен сәйкестендіріледі.
- Бөлім нөлге тең болмауы, түбір астындағы өрнек теріс болмауы сияқты қолдану шарттарын міндетті түрде тексер.
- Формуланы жаттап қана қоймай, мәндерді қоймас бұрын қай шама нені білдіретінін жаз.

**Толық үлгімен оқу тәртібі:**
1. Берілген шамаларды жаз.
2. Нені табу керегін белгіле.
3. Қажетті формуланы толық жаз.
4. Белгілі мәндерді формулаға қой.
5. Әр амалды ретімен орында.
6. Шыққан нәтижені шартпен тексер.
{learning_visual_markdown(topic)}

**Жалпы шешу алгоритмі:**
1-қадам. Есепте не берілгенін және нені табу керегін жаз.
2-қадам. Осы тақырыпқа сәйкес формула немесе ережені таңда.
3-қадам. Берілген мәндерді формулаға таңбасымен бірге қой.
4-қадам. Амалдарды ретімен орында және аралық нәтижені тексер.
5-қадам. Жауапты бастапқы шартқа қойып тексер.

**Жиі қате:** таңбаға, амалдардың ретіне және өлшем бірлігіне назар аудармау."""
    # Жеке практика да тек тексерілген жауап банкін пайдаланады.
    practice = adaptive_fallback(grade, topic, level_name, weak, diagnostic_answers, score)
    return theory, practice

def practice_full_solution(state):
    """Ағымдағы жеке есептің формуласын және толық шығарылуын сұрағанда ашады."""
    if not state or not state.get("practice"):
        return "<div class='warn'>Алдымен бастапқы диагностиканы аяқтаңыз.</div>"
    i=min(state.get("practice_i",0),len(state["practice"])-1)
    task=state["practice"][i]
    section,formulas=formula_for_current_task(task,state.get("grade",""),state.get("topic",""))
    formula_text="\n".join(f"- `{x}`" for x in formulas) or "- Есеп шартынан қажетті амал немесе формуланы анықта."
    prompt=f"""Мына мектеп математикасы есебінің толық, қатесіз шешуін қазақша түсіндір.
Сынып: {state.get('grade')}. Тақырып: {state.get('topic')}. Деңгей: {state.get('level')}.
Есеп: {task.get('q')}
Тексерілген дұрыс жауап: {task.get('a')}
Қолданылатын формула бөлімі: {section}
Формулалар: {'; '.join(formulas)}
Бағыт: {task.get('hint','')}
Міндетті құрылым: Берілгені → Табу керек → Формула (әр таңбаның мағынасы) → мәндерді қою → барлық аралық есептеу қадамдары → Жауап → бастапқы шартпен тексеру.
Дұрыс жауапты өзгертпе. Формулаларды математикалық символдармен анық жаз."""
    solved=ai_text(prompt)
    if not solved:
        solved=f"""### 📖 Толық талдау
**Есеп:** {task.get('q')}

**Қажетті формула немесе ереже ({section or state.get('topic')}):**
{formula_text}

**Шығару реті:**
1. Есептегі белгілі шамаларды белгіле.
2. `{task.get('hint','Тақырыпқа сәйкес формуланы таңда.')}`
3. Белгілі мәндерді формулаға қойып, амалдарды ретімен орында.
4. Нәтижені есеп шартына қайта қойып тексер.

**Тексерілген жауап:** `{task.get('a')}`"""
    if state.get("language")=="Русский": solved=to_russian(solved)
    return solved

def new_profile(name, grade, letter, topic_choice, custom_topic, language):
    topic = resolved_topic(topic_choice, custom_topic)
    if not name.strip() or not topic:
        return {}, "<div class='warn'>Аты-жөні мен тақырыпты толық енгізіңіз.</div>"
    login_time=datetime.now().strftime("%d.%m.%Y %H:%M")
    session_id=hashlib.sha1(f"{name}-{grade}-{letter}-{topic}-{datetime.now().isoformat()}".encode()).hexdigest()[:14]
    state = {"session_id":session_id,"login_time":login_time,"language":language or "Қазақша","name":name.strip(),"grade":str(grade),"letter":letter,"topic":topic,"initial":None,"level":None,"weak":"","practice":[],"practice_i":0,"practice_try":0,"practice_correct":0,"final":None}
    update_student_record(state,**{"Кезең":"Профиль сақталды","Орындалған":"0 тапсырма"})
    if state["language"]=="Русский":
        return state, f"<div class='good'><h3>✅ Профиль сохранён, {name}!</h3><p><b>{grade} «{letter}»</b> · {to_russian(topic)}</p><h3>➡️ СЛЕДУЮЩИЙ ШАГ</h3><p>Откройте раздел <b>«🧭 Входная диагностика»</b> и выполните 5 заданий.</p></div>"
    return state, f"<div class='good'><h3>✅ Профиль сақталды, {name}!</h3><p><b>{grade} «{letter}»</b> · {topic}</p><h3>➡️ КЕЛЕСІ ҚАДАМ</h3><p>Жоғарғы мәзірден <b>«🧭 Бастапқы диагностика»</b> бөлімін басып, 5 тапсырманы орында.</p></div>"

def start_initial(state):
    if not state: return state,"<div class='warn'>Алдымен «Оқушы профилі» бөлімін толтырыңыз.</div>","",gr.update(visible=False),gr.update(visible=False)
    state["initial"]={"tasks":generate_tasks(state["grade"],state["topic"],"бастапқы диагностика",5),"i":0,"correct":0,"answers":[]}
    q=state["initial"]["tasks"][0]
    update_student_record(state,**{"Кезең":"Бастапқы диагностика","Орындалған":"0 / 5"})
    msg="<div class='good'>Диагностика началась. 5 заданий проверяют основные навыки по теме.</div>" if state.get("language")=="Русский" else "<div class='good'>Диагностика басталды. 5 тапсырма тақырыптың негізгі дағдыларын толық тексереді.</div>"
    return state,msg,task_card_html(q,1,5,"Бастапқы диагностика",state["topic"],state.get("language","Қазақша")),gr.update(visible=True,value=""),gr.update(visible=True)

def submit_initial(answer,state):
    d=state.get("initial") if state else None
    if not d: return state,"<div class='warn'>Диагностиканы бастаңыз.</div>","",gr.update(),gr.update(),"", "", gr.update(visible=False)
    if not str(answer).strip(): return state,"<div class='warn'>Жауап енгізіңіз.</div>","",gr.update(),gr.update(),"", "", gr.update()
    t=d["tasks"][d["i"]]; ok=answer_is_correct(answer,t["a"]); d["correct"]+=int(ok); d["answers"].append({"skill":t["skill"],"q":t["q"],"ok":ok})
    fb="<div class='good'>✅ Жауап қабылданды.</div>" if ok else f"<div class='guide'>🧭 Қате бар. Дұрыс жауапты ашпаймын. Бағыт: {t['hint']}</div>"
    d["i"]+=1
    update_student_record(state,**{"Кезең":"Бастапқы диагностика","Орындалған":f"{d['i']} / 5","Соңғы жауап":str(answer),"Жауап статусы":"Дұрыс" if ok else "Қате — қайта оқыту қажет"})
    if d["i"]<5:
        q=d["tasks"][d["i"]]; return state,fb,task_card_html(q,d["i"]+1,5,"Бастапқы диагностика",state["topic"],state.get("language","Қазақша")),gr.update(value="",visible=True),gr.update(visible=True),"","",gr.update(visible=False)
    score=round(d["correct"]/5*100); lv,ico,rec=score_level(score); weak=", ".join(dict.fromkeys(x["skill"] for x in d["answers"] if not x["ok"])) or "Олқылық анықталмады"
    state["level"],state["weak"]=lv,weak; theory,practice=generate_learning(state["grade"],state["topic"],lv,weak,d["answers"],score); state["practice"]=practice; state["practice_i"]=0; state["practice_try"]=0; state["practice_correct"]=0; state["correction_task"]=None; state["correction_done"]=0
    update_student_record(state,**{"Кезең":"Бастапқы диагностика аяқталды","Орындалған":"5 / 5","Бастапқы":score,"Деңгей":lv,"Қиындық":weak})
    pq=practice[0]
    summary=f"<div class='result'><div class='result-icon'>{ico}</div><h2>{score}% · {lv} деңгей</h2><p>{rec}</p><p><b>Назар аударатын дағды:</b> {weak}</p><h3>➡️ КЕЛЕСІ ҚАДАМ</h3><p>Жоғарғы мәзірден <b>«📘 Жеке оқу»</b> бөлімін бас. Теория мен деңгейіңе сәйкес тапсырмалар сол жерде ашылды.</p></div>"
    if state.get("language")=="Русский": theory=to_russian(theory)
    phtml=task_card_html(pq,1,len(practice),"Жеке тапсырма",state["topic"],state.get("language","Қазақша"))
    return state,fb,summary,gr.update(visible=False),gr.update(visible=False),theory,phtml,gr.update(visible=True,value="")

def learning_path_html(state, current="Жеке оқу"):
    steps=["Диагностика","Теория/формула","Жеке тапсырма","PISA","Қатемен жұмыс","Қорытынды диагностика"]
    done=set()
    if state and state.get("initial"): done.add("Диагностика")
    if state and state.get("practice_i",0)>0: done.update(["Теория/формула","Жеке тапсырма"])
    if state and state.get("pisa") and state["pisa"].get("i",0)>0: done.add("PISA")
    if state and state.get("correction_done",0)>0: done.add("Қатемен жұмыс")
    if state and state.get("final") and state["final"].get("i",0)>=5: done.add("Қорытынды диагностика")
    chips=[]
    for x in steps:
        mark="✓" if x in done else ("●" if x==current else "○")
        chips.append(f"<span style='padding:8px 12px;border-radius:18px;background:#eef2ff;margin:4px;display:inline-block'><b>{mark}</b> {x}</span>")
    weak=(state or {}).get("weak") or "диагностика нәтижесіне сай дағды"
    return "<div class='helper-box'><h3>🧭 Менің жеке оқу траекториям</h3>"+" → ".join(chips)+f"<p><b>AI-MATH ұсынысы:</b> алдымен әлсіз дағдыны бекітеміз: {weak}. Кейін PISA және қорытынды тексеруге өтеміз.</p></div>"

def _correction_task_for(state, original):
    """Pick a different verified task for the same/closest skill and topic."""
    pool=[]
    try: pool=curated_tasks(state.get("grade"),state.get("topic")) or []
    except: pool=[]
    target=str(original.get("skill","")).lower(); oq=_task_key(original)
    candidates=[x for x in pool if _task_key(x)!=oq]
    candidates.sort(key=lambda x: (target not in str(x.get("skill","")).lower(), -_skill_relevance(x,[target])))
    if candidates: return dict(candidates[0])
    # safe fallback: same task is rechecked only if no second verified task exists
    x=dict(original); x["objective"]="Түзету тапсырмасы · "+str(original.get("skill","дағды")); return x

def submit_practice(answer,state):
    if not state or not state.get("practice"): return state,"<div class='warn'>Алдымен бастапқы диагностиканы аяқтаңыз.</div>","",gr.update()
    # Dedicated correction stage required by round-2 rubric.
    if state.get("correction_task"):
        ct=state["correction_task"]
        if answer_is_correct(answer,ct["a"]):
            state["correction_done"]=state.get("correction_done",0)+1; state["correction_task"]=None
            state["practice_i"]+=1; state["practice_try"]=0
            fb="<div class='good'><h3>✅ ҚАТЕ ТҮЗЕТІЛДІ</h3><p>Ұқсас тапсырманы дұрыс орындадың. Енді келесі дағдыға өтеміз.</p></div>"
        else:
            return state,f"<div class='guide'><b>🔄 Түзету тапсырмасы:</b> {ct.get('hint','Формуланы қолданып қайта тексер.')} Қайта орында.</div>",task_card_html(ct,1,1,"ТҮЗЕТУ ТАПСЫРМАСЫ",state["topic"],state.get("language","Қазақша")),gr.update(value="")
    else:
        i=state["practice_i"]
        if i>=len(state["practice"]): return state,"<div class='good'>Практика аяқталған.</div>","",gr.update(visible=False)
        t=state["practice"][i]
        if answer_is_correct(answer,t["a"]):
            state["practice_correct"]+=1; state["practice_i"]+=1; state["practice_try"]=0
            fb="<div class='good'>✅ Дұрыс! Келесі қадамға өттің.</div>"
            update_student_record(state,**{"Кезең":"Жеке оқу","Орындалған":f"{state['practice_i']} / {len(state['practice'])}","Соңғы жауап":str(answer),"Жауап статусы":"Дұрыс"})
        else:
            state["practice_try"]+=1
            update_student_record(state,**{"Кезең":"Жеке оқу — қатемен жұмыс","Орындалған":f"{state['practice_i']} / {len(state['practice'])}","Соңғы жауап":str(answer),"Жауап статусы":f"Қате, {state['practice_try']}-әрекет"})
            loc=localize_task(t,state.get("language"))
            if state["practice_try"]==1:
                return state,f"<div class='guide'><b>🔍 1-бағыт:</b> {loc['hint']}<br>Дайын жауап берілмейді — өз жауабыңды түзет.</div>",task_card_html(t,i+1,len(state["practice"]),"Жеке тапсырма",state["topic"],state.get("language","Қазақша")),gr.update(value="")
            if state["practice_try"]==2:
                return state,f"<div class='guide'><b>🧠 Қате талдауы:</b> {loc.get('explain',t['hint'])}<br><b>Қажетті дағды:</b> {loc.get('skill','')}</div>",task_card_html(t,i+1,len(state["practice"]),"Жеке тапсырма",state["topic"],state.get("language","Қазақша")),gr.update(value="")
            # third wrong answer -> explain, then MUST solve a correction task before moving on
            state["correction_task"]=_correction_task_for(state,t)
            ct=state["correction_task"]
            fb=f"<div class='guide'><h3>🔍 ҚАТЕНІ ИНТЕЛЛЕКТУАЛДЫ ТАЛДАУ</h3><p>{loc.get('explain','Шешу алгоритмін қайта қара.')}</p><p><b>Дұрыс жауап үлгісі:</b> {t['a']}</p><p>Енді осы дағдыны бекітетін арнайы түзету тапсырмасын орында.</p></div>"
            return state,fb,task_card_html(ct,1,1,"🔄 ТҮЗЕТУ ТАПСЫРМАСЫ",state["topic"],state.get("language","Қазақша")),gr.update(value="",visible=True)
    if state["practice_i"]<len(state["practice"]):
        update_student_record(state,**{"Кезең":"Жеке оқу","Орындалған":f"{state['practice_i']} / {len(state['practice'])}"})
        q=state["practice"][state["practice_i"]]
        return state,fb,learning_path_html(state,"Жеке тапсырма")+task_card_html(q,state["practice_i"]+1,len(state["practice"]),"Жеке тапсырма",state["topic"],state.get("language","Қазақша")),gr.update(value="",visible=True)
    practice_score=round(state["practice_correct"]/max(1,len(state["practice"]))*100)
    update_student_record(state,**{"Кезең":"Жеке оқу аяқталды","Орындалған":f"{len(state['practice'])} / {len(state['practice'])}","Жеке оқу":practice_score})
    return state,fb,learning_path_html(state,"PISA")+f"<div class='result'><h2>✅ Жеке оқу аяқталды</h2><p>Дұрыс орындалғаны: {state['practice_correct']} / {len(state['practice'])}</p><p>Түзетілген қателер: <b>{state.get('correction_done',0)}</b></p><h3>➡️ КЕЛЕСІ ҚАДАМ: 🌍 PISA</h3></div>",gr.update(visible=False)

def make_pisa(state):
    if not state: return state,"<div class='warn'>Алдымен профильді толтырыңыз.</div>","",gr.update(visible=False),gr.update(visible=False)
    tasks=pisa_tasks_for_topic(state["grade"],state["topic"],state.get("level") or "Базалық")
    state["pisa"]={"tasks":tasks,"i":0,"correct":0,"tries":0}
    q=tasks[0]
    update_student_record(state,**{"Кезең":"PISA тапсырмалары","Орындалған":"0 / 3"})
    card=learning_path_html(state,"PISA")+task_card_html(q,1,3,f"PISA · {q['context']}",state["topic"],state.get("language","Қазақша"))
    return state,f"<div class='good'>🌍 Таңдалған тақырып: <b>{state['topic']}</b>. Осы тақырыпқа сәйкес үш өмірлік PISA тапсырмасы дайын.</div>",card,gr.update(visible=True,value=""),gr.update(visible=True)

def check_pisa(answer,state):
    if not state or not state.get("pisa"): return state,"<div class='warn'>PISA тапсырмаларын ашыңыз.</div>","",gr.update(),gr.update()
    d=state["pisa"]; t=d["tasks"][d["i"]]
    if not str(answer or "").strip(): return state,"<div class='warn'>Жауап немесе есептеу жолын енгіз.</div>",gr.update(),gr.update(),gr.update()
    if not answer_is_correct(answer,t["a"]):
        d["tries"]+=1
        if d["tries"]<2:
            return state,f"<div class='guide'>🧭 Бағыт: {t['hint']} Жауабыңды түзетіп, қайта жібер.</div>",gr.update(),gr.update(value=answer,visible=True),gr.update(visible=True)
        fb=f"<div class='guide'><b>Толық талдау:</b> {t['explain']} <b>Жауап: {t['a']}</b></div>"
    else:
        d["correct"]+=1; fb=f"<div class='good'>✅ Дұрыс! <b>Негіздеме:</b> {t['explain']}</div>"
    d["i"]+=1; d["tries"]=0
    update_student_record(state,**{"Кезең":"PISA тапсырмалары","Орындалған":f"{d['i']} / 3"})
    if d["i"]<3:
        q=d["tasks"][d["i"]]
        card=task_card_html(q,d["i"]+1,3,f"PISA · {q['context']}",state["topic"],state.get("language","Қазақша"))
        return state,fb,card,gr.update(value="",visible=True),gr.update(visible=True)
    pisa_score=round(d["correct"]/3*100)
    update_student_record(state,**{"Кезең":"PISA аяқталды","Орындалған":"3 / 3","PISA":pisa_score})
    summary=f"<div class='result'><h2>🌍 PISA бөлімі аяқталды</h2><p>Дұрыс орындалғаны: <b>{d['correct']} / 3</b></p><p>Сен нақты жағдаятты математикалық модельге айналдырып көрдің.</p><h3>Қосымша мүмкіндік</h3><p>«🏆 Олимпиадалық есептер» бөлімінде күрделі есептің теориясы мен толық шешуін зертте немесе «🧠 Нейрожаттығуларға» өт.</p></div>"
    return state,fb,summary,gr.update(value="",visible=False),gr.update(visible=False)

def task_helper(state, section):
    """Ағымдағы тапсырмаға бөлімнің мақсатына сай көмек береді."""
    if not state:
        return "<div class='warn'>Алдымен оқушы профилін толтырыңыз.</div>"
    task=None
    if section=="initial" and state.get("initial"):
        d=state["initial"]
        if d.get("i",0)<len(d.get("tasks",[])): task=d["tasks"][d["i"]]
    elif section=="practice" and state.get("practice"):
        i=state.get("practice_i",0)
        if i<len(state["practice"]): task=state["practice"][i]
    elif section=="pisa" and isinstance(state.get("pisa"),dict):
        d=state["pisa"]
        if d.get("i",0)<len(d.get("tasks",[])): task=d["tasks"][d["i"]]
    elif section=="final" and state.get("final"):
        d=state["final"]
        if d.get("i",0)<len(d.get("tasks",[])): task=d["tasks"][d["i"]]
    if not task:
        return "<div class='guide'>Алдымен осы бөлімнің тапсырмасын бастаңыз. Тапсырма ашылған соң мен нақты көмек беремін.</div>"
    grade=state.get("grade","5"); topic=state.get("topic","математика")
    # PISA бөлімінде көмек профильдегі жалпы тақырыптан емес, дәл экрандағы есептен алынады.
    if section=="pisa":
        f_section,f_list=formula_for_current_task(task,grade,topic)
    else:
        f_section,f_list=formula_for_topic(grade,topic)
    task_focus=task.get("skill") or task.get("objective") or topic
    is_diagnostic=section in ("initial","final")
    if is_diagnostic:
        # Бақылау бөлімінде формуланың толық жазылуы мен шешу жолы ашылмайды.
        formula_note=f_section or task.get("skill",topic)
        prompt=f"""Сен AI-G математика көмекшісісің. {grade}-сынып. Профиль тақырыбы: {topic}. Экрандағы нақты тапсырма: {task.get('q','')}
Нақты тапсырманың дағдысы: {task_focus}. Көмекті тек экрандағы есепке сәйкестендір; профиль тақырыбына қатысы жоқ формуланы қолданба.
Бұл ДИАГНОСТИКА/БАҚЫЛАУ бөлімі. Жауапты, толық формуланы және толық шешу жолын ашпа.
Оқушыға тек: 1) не белгілі/не табу керек; 2) қолданылатын формуланың немесе ереженің АТАУЫН ғана; 3) бірінші ойлау бағытын; 4) өзін тексеруге бір сұрақ бер.
Формуланың әріптік өрнегін жазба."""
        ai=ai_text(prompt) if GEMINI_API_KEY else None
        body=ai.replace("\n","<br>") if ai else (f"<b>1. Есепті бөл:</b> белгілі шамаларды және ізделіндіні белгіле.<br><b>2. Қажет ереже/формула атауы:</b> {formula_note}.<br><b>3. Бағыт:</b> {task.get('hint','Шарттағы байланысқа назар аудар.')}<br><b>4. Өзіңді тексер:</b> Қай шама белгісіз және оны табуға қай байланыс көмектеседі?")
        note="Бұл бақылау бөлімі: толық формула мен дайын шешім көрсетілмейді."
    else:
        formulas="; ".join(f_list[:5]) if f_list else "Тақырыпқа сәйкес негізгі формула/ереже"
        prompt=f"""Сен AI-G математика көмекшісісің. {grade}-сынып. Профиль тақырыбы: {topic}. Экрандағы нақты тапсырма: {task.get('q','')}
Нақты тапсырманың дағдысы: {task_focus}. Көмекті тек экрандағы есепке сәйкестендір; профиль тақырыбына қатысы жоқ формуланы қолданба.
Бұл ОҚЫТУ бөлімі. Оқушы «түсінбедім» деді, сондықтан толық үйрет:
1) не белгілі және нені табу керек; 2) дәл қажет формуланы толық жаз; 3) формуладағы таңбаларды түсіндір; 4) мәндерді қалай қоятынын көрсет; 5) есептің алғашқы 1–2 қадамын түсіндір; 6) ұқсас шағын мысал келтір; 7) оқушы өзі жалғастыратын сұрақ қой.
Тақырып анықтамалығы: {formulas}
Егер кескін қажет болса, қарапайым ASCII кескін қос. Соңғы жауапты бірден бермей, оқушыны келесі қадамға жетеле."""
        ai=ai_text(prompt) if GEMINI_API_KEY else None
        if ai: body=ai.replace("\n","<br>")
        else:
            formula_html="<br>".join(f"• <b>{x}</b>" for x in f_list[:5]) if f_list else "• Тақырып ережесін қолдан."
            body=(f"<b>1. Не белгілі?</b> Шарттағы сандар мен шамаларды белгіле.<br><b>2. Дәл осы есепке қажетті формула:</b><br>{formula_html}<br><b>3. Неге осы формула?</b> Ол {task_focus} дағдысындағы шамалардың байланысын көрсетеді.<br><b>4. Алғашқы қадам:</b> {task.get('hint','Берілген мәндерді формулаға қой.')}<br><b>5. Әрі қарай:</b> мәндерді формулаға қойып, амалдарды ретімен орында.")
        note="Бұл оқыту бөлімі: формула мен бағыт ашық көрсетіледі, бірақ соңғы жауапты өзің аяқтайсың."
    return f"<div class='helper-box'><h3>🤖 AI-G көмекшісінің бағыты</h3><p>{body}</p><small>{note}</small></div>"

def current_task_visual(state, section):
    """Көрнекілікті тек оқушы арнайы батырманы басқанда ашады."""
    if not state: return "<div class='warn'>Алдымен профильді толтырыңыз.</div>"
    task=None
    if section=="initial" and state.get("initial"):
        d=state["initial"]; i=d.get("i",0)
        if i<len(d.get("tasks",[])): task=d["tasks"][i]
    elif section=="practice" and state.get("practice"):
        i=state.get("practice_i",0)
        if i<len(state["practice"]): task=state["practice"][i]
    elif section=="pisa" and isinstance(state.get("pisa"),dict):
        d=state["pisa"]; i=d.get("i",0)
        if i<len(d.get("tasks",[])): task=d["tasks"][i]
    elif section=="final" and state.get("final"):
        d=state["final"]; i=d.get("i",0)
        if i<len(d.get("tasks",[])): task=d["tasks"][i]
    if not task: return "<div class='guide'>Алдымен тапсырманы ашыңыз.</div>"
    visual=task_visual_html(task,state.get("topic",""))
    if visual: return visual
    return "<div class='helper-box'><h3>👁️ Кескін қажет емес</h3><p>Бұл есеп сызбаға емес, сандық немесе алгебралық амалдарға негізделген. Көмекші батырмасынан формула мен алғашқы қадамды көре аласыз.</p></div>"

def start_final(state):
    if not state or not state.get("level"): return state,"<div class='warn'>Алдымен бастапқы диагностиканы аяқтаңыз.</div>","",gr.update(visible=False),gr.update(visible=False)
    state["final"]={"tasks":generate_tasks(state["grade"],state["topic"],"қорытынды",5,state["level"]),"i":0,"correct":0}
    q=state["final"]["tasks"][0]
    update_student_record(state,**{"Кезең":"Қорытынды диагностика","Орындалған":"0 / 5"})
    return state,"<div class='good'>Итоговая диагностика началась.</div>" if state.get("language")=="Русский" else "<div class='good'>Қорытынды 5 тапсырмалық диагностика басталды.</div>",task_card_html(q,1,5,"Қорытынды диагностика",state["topic"],state.get("language","Қазақша")),gr.update(visible=True,value=""),gr.update(visible=True)

def submit_final(answer,state):
    d=state.get("final") if state else None
    if not d: return state,"<div class='warn'>Қорытынды диагностиканы бастаңыз.</div>","",gr.update(),gr.update()
    t=d["tasks"][d["i"]]; ok=answer_is_correct(answer,t["a"]); d["correct"]+=int(ok); d["i"]+=1
    update_student_record(state,**{"Кезең":"Қорытынды диагностика","Орындалған":f"{d['i']} / 5"})
    fb="<div class='good'>✅ Дұрыс.</div>" if ok else f"<div class='guide'>🧭 Бағыт: {t['hint']}</div>"
    if d["i"]<5:
        q=d["tasks"][d["i"]]; return state,fb,task_card_html(q,d["i"]+1,5,"Қорытынды диагностика",state["topic"],state.get("language","Қазақша")),gr.update(value="",visible=True),gr.update(visible=True)
    final_score=round(d["correct"]/5*100); initial_score=round(state["initial"]["correct"]/5*100); growth=final_score-initial_score; lv,ico,rec=score_level(final_score)
    update_student_record(state,**{"Кезең":"Оқу аяқталды","Орындалған":"Барлық кезең","Бастапқы":initial_score,"Қорытынды":final_score,"Өсу":growth,"Деңгей":lv,"Қиындық":state["weak"]})
    report=learning_path_html(state,"Қорытынды диагностика")+f"<div class='result'><div class='result-icon'>{ico}</div><h2>📊 ОҚУШЫНЫҢ ДАМУ КАРТАСЫ</h2><p><b>Бастапқы нәтиже:</b> {initial_score}% → <b>Қорытынды:</b> {final_score}%</p><p><b>Өсу:</b> {growth:+d}% · <b>Жаңа деңгей:</b> {lv}</p><p><b>Анықталған әлсіз дағды:</b> {state.get('weak') or 'анықталмады'}</p><p><b>Түзетілген қателер:</b> {state.get('correction_done',0)}</p><p>{rec}</p><p>Нәтиже мұғалім кабинетіне сақталды.</p></div>"
    return state,fb,report,gr.update(visible=False),gr.update(visible=False)

def ask_assistant(question,state,history):
    if not question.strip(): return history,""
    context=f"Оқушы: {state.get('grade','?')}-сынып, тақырып: {state.get('topic','математика')}, деңгей: {state.get('level','анықталмаған')}" if state else "Математика оқушысы"
    prompt=f"""Сен AI-G ЖИ-ассистентсің. {context}. Оқушы сұрағы: {question}
ҚР бағдарламасына сай қазақша, ашық және түсінікті жауап бер.
Егер формула сұралса: формуланың өзін жеке жолға, таңбалардың мағынасын, қолдану шартын және бір шағын мысалды көрсет.
Егер есеп сұралса: дайын жауапты бірден айтпай, алдымен бағыттаушы сұрақ, кейін ереже, содан соң ұқсас мысал бер.
Математикалық x², √, π, ∫, log, sin, cos таңбаларын дұрыс сақта. Оқушының жасына сәйкес артық терминсіз түсіндір."""
    reply=ai_text(prompt) or "Сұрағыңды үш бөлікке бөлейік: не белгілі, нені табу керек, қандай ереже сәйкес? Алдымен есеп шартынан белгілі шамаларды жазып көр."
    history=(history or [])+[{"role":"user","content":question},{"role":"assistant","content":reply}]
    return history,""

def ask_assistant_multimodal(question,image,state,history):
    question=str(question or "").strip()
    if not question and image is None: return history,"",None
    context=f"{state.get('grade','?')}-сынып, тақырып: {state.get('topic','математика')}, деңгей: {state.get('level','анықталмаған')}" if state else "5–11-сынып математикасы"
    request=question or "Суреттегі математикалық есепті танып, шығару жолын түсіндір."
    prompt=f"""Сен AI-G — Қазақстан бағдарламасына сай математика көмекшісісің. Оқушы контексі: {context}.
Оқушының сұрағы: {request}
Кез келген математикалық тақырыпқа қазақша, жасына сай, анық жауап бер. Формулаларды x², √, π, ∫, log, sin, cos таңбаларымен дұрыс жаз.
Есеп болса, бұл көмекші/оқыту режимі екенін ескер: 1) берілгені; 2) қолданылатын формуланы толық әрі жеке жолға жаз; 3) формуладағы таңбаларды түсіндір; 4) қадамдық шығару жолын көрсет; 5) кескін керек болса ASCII кескін бер; 6) тексеру тәсілін көрсет. Комбинаторика сияқты тақырыпта Pₙ, Aₙᵏ, Cₙᵏ формулаларының қайсысы не үшін таңдалатынын міндетті түрде түсіндір.
Сурет берілсе, суреттегі шарт пен оқушының жазуын мұқият таны, дұрыс қадамдарын атап, бірінші қатені жұмсақ түсіндір."""
    if image is not None and not GEMINI_API_KEY:
        reply="📷 Фото есепті тану үшін Colab Secrets бөліміне GEMINI_API_KEY енгізіңіз. Ал есептің мәтінін осында жазсаңыз, дәл қазір түсіндіріп көмектесемін."
    else:
        reply=ai_text(prompt,image) if image is not None else ai_text(prompt)
        reply=reply or "Есепті бірге талдайық: не берілгенін, нені табу керегін және қандай формула сәйкес екенін жазыңыз. Мен әр қадамда бағыт беремін."
    shown=("📷 Фото есеп"+(f" — {question}" if question else "")) if image is not None else question
    history=(history or [])+[{"role":"user","content":shown},{"role":"assistant","content":reply}]
    return history,"",None

def analyze_photo(image,state):
    if image is None: return "<div class='warn'>Алдымен анық түсірілген суретті жүктеңіз.</div>"
    if not GEMINI_API_KEY: return "<div class='warn'>Суретті ЖИ арқылы тану үшін Colab Secrets-ке GEMINI_API_KEY қосыңыз.</div>"
    context=f"{state.get('grade','?')}-сынып, {state.get('topic','математика')}" if state else "математика"
    prompt=f"""Бұл {context} оқушысының дәптер жұмысы. Суреттегі есеп пен шешу қадамдарын таны.
Дұрыс қадамдарды ата; алғашқы қатені тап; дұрыс жауапты бірден бермей бағыттаушы сұрақ қой; бағалау критерийі бойынша қысқа кері байланыс бер. Қазақша жауап бер."""
    reply=ai_text(prompt,image)
    return f"<div class='guide'><h3>📷 ЖИ талдауы</h3><p>{(reply or 'Суретті талдау қызметі уақытша қолжетімсіз.').replace(chr(10),'<br>')}</p></div>"

def teacher_login(code):
    if str(code).strip()!=TEACHER_CODE: return "<div class='bad'>🔒 Код қате.</div>",gr.update(visible=False),pd.DataFrame(),pd.DataFrame(),level_chart()
    return "<div class='good'>✅ Мұғалім кабинеті ашылды.</div>",gr.update(visible=True),class_summary(),student_summary(),level_chart()

def student_summary():
    cols=["Кіру уақыты","Соңғы белсенділік","Оқушы","Сынып","Тақырып","Кезең","Орындалған","Соңғы жауап","Жауап статусы","Бастапқы","Жеке оқу","PISA","Қорытынды","Өсу","Деңгей","Қиындық"]
    rows=load_results()
    # Бұрынғы жазбаларды да жоғалтпай, жаңа бағандарға сәйкестендіреміз.
    normalized=[]
    for r in rows:
        x=dict(r)
        if "Кіру уақыты" not in x: x["Кіру уақыты"]=x.get("Күні","")
        if "Кезең" not in x: x["Кезең"]="Оқу аяқталды"
        normalized.append(x)
    return pd.DataFrame(normalized).reindex(columns=cols) if normalized else pd.DataFrame(columns=cols)

def class_summary():
    df=student_summary()
    if df.empty: return pd.DataFrame(columns=["Сынып","Кірген оқушы","Бастапқыны аяқтаған","Оқуды аяқтаған","Орташа бастапқы","Орташа қорытынды","Орташа өсу"])
    for col in ["Бастапқы","Қорытынды","Өсу"]: df[col]=pd.to_numeric(df[col],errors="coerce")
    rows=[]
    for cls,g in df.groupby("Сынып",dropna=False):
        rows.append({"Сынып":cls,"Кірген оқушы":g["Оқушы"].nunique(),
                     "Бастапқыны аяқтаған":int(g["Бастапқы"].notna().sum()),
                     "Оқуды аяқтаған":int(g["Қорытынды"].notna().sum()),
                     "Орташа бастапқы":round(g["Бастапқы"].mean(),1) if g["Бастапқы"].notna().any() else None,
                     "Орташа қорытынды":round(g["Қорытынды"].mean(),1) if g["Қорытынды"].notna().any() else None,
                     "Орташа өсу":round(g["Өсу"].mean(),1) if g["Өсу"].notna().any() else None})
    return pd.DataFrame(rows)

def level_chart():
    df = student_summary()
    fig, ax = plt.subplots(figsize=(7.5,4.2))
    fig.patch.set_facecolor("#eef2ff"); ax.set_facecolor("#ffffff")
    order=["Бастапқы","Базалық","Жеткілікті","Жоғары","Шебер"]
    colors=["#ff4d6d","#ff9f1c","#00b4d8","#22c55e","#8b5cf6"]
    counts=[int((df["Деңгей"]==x).sum()) if not df.empty else 0 for x in order]
    bars=ax.bar(order,counts,color=colors,width=.64,edgecolor="#ffffff",linewidth=2)
    ax.set_title("Оқушылардың деңгей бойынша таралуы",fontsize=14,fontweight="bold",color="#172554")
    ax.set_ylabel("Оқушы саны",color="#334155",fontweight="bold"); ax.grid(axis="y",alpha=.15,linestyle="--")
    ax.tick_params(axis="x",colors="#172554",labelsize=10)
    for bar,value in zip(bars,counts): ax.text(bar.get_x()+bar.get_width()/2,value+.03,str(value),ha="center",fontweight="bold",color="#172554")
    for side in ("top","right"): ax.spines[side].set_visible(False)
    fig.tight_layout(); return fig

