def sen_calculated_answer(task):
    """ЕББҚ тапсырмасының дұрыс жауабын мәтіндегі сақталған жауаптан емес, амалдан есептейді."""
    kind=str(task.get("kind", "")); left=int(task.get("left",0)); right=int(task.get("right",0))
    if kind.startswith("add"): return left+right
    if kind.startswith("sub"): return left-right
    if kind.startswith("mul"): return left*right
    if kind.startswith("div"):
        if right==0 or left%right!=0: raise ValueError(f"Бөлу тапсырмасы қате құрылған: {task.get('q')}")
        return left//right
    question=str(task.get("q",""))
    match=re.match(r"\s*([0-9×·÷+−\-*/(). ]+)",question)
    expression=(match.group(1) if match else question.split("өрнегінің")[0]).strip()
    expression=expression.replace("×","*").replace("·","*").replace("÷","/").replace("−","-")
    if not re.fullmatch(r"[0-9+\-*/(). ]+",expression):
        raise ValueError(f"Өрнек қауіпсіз есептелмейді: {task.get('q')}")
    value=eval(expression,{"__builtins__":{}},{})
    return int(value) if float(value).is_integer() else value

def verify_and_repair_sen_banks():
    """ЕББҚ банктеріндегі жауап пен жауап нұсқаларын арифметикамен автоматты сәйкестендіреді."""
    banks=[SEN_DIAGNOSTIC]
    banks.extend(SEN_DIAGNOSTIC_BANKS.values())
    banks.extend(SEN_PRACTICE.values())
    checked=0
    for bank in banks:
        for task in bank:
            correct=str(sen_calculated_answer(task)).replace(".0","")
            task["a"]=correct
            choices=[str(x) for x in task.get("choices",[])]
            if correct not in choices:
                choices=(choices+[correct])[-3:]
            task["choices"]=choices
            assert task["a"] in task["choices"], task["q"]
            checked+=1
    return checked

SEN_VERIFIED_COUNT=verify_and_repair_sen_banks()

def sen_level(score):
    if score <= 1: return "Бастапқы қолдау", "🌱", "Санау, заттарды сәйкестендіру және бір қадамдық қосу/азайту"
    if score == 2: return "Негізгі амалдар", "⭐", "Қосу мен азайтуды көрнекілік арқылы бекіту"
    return "Көбейту және бөлу", "🚀", "Көбейту, бөлу және амалдардың орындалу реті"

def sen_objects(symbol, count, leaving=False):
    cls="sen-item sen-leave" if leaving else "sen-item"
    return "".join(f"<span class='{cls}' style='animation-delay:{i*.12:.2f}s'>{symbol}</span>" for i in range(count))

def sen_localized_task(task, language="Қазақша"):
    lang={"Қазақша":"kk","Русский":"ru","English":"en"}.get(language,"kk")
    kind=task.get("kind",""); a=int(task.get("left",0)); b=int(task.get("right",0))
    noun="алма" if "apple" in kind else "зат"
    if kind.startswith("add"):
        texts={"kk":f"{a} {noun}ға тағы {b} {noun} қосылды. Барлығы неше {noun} болды?","ru":f"К {a} предметам добавили ещё {b}. Сколько предметов стало всего?","en":f"There were {a} objects. {b} more were added. How many objects are there altogether?"}
    elif kind.startswith("sub"):
        texts={"kk":f"{a} заттың {b}-еуі алынды. Неше зат қалды?","ru":f"Было {a} предметов. Убрали {b}. Сколько предметов осталось?","en":f"There were {a} objects. {b} were taken away. How many are left?"}
    elif kind.startswith("mul"):
        texts={"kk":f"{a} топтың әрқайсысында {b} зат бар. Барлығы неше зат?","ru":f"Есть {a} групп, в каждой по {b} предмета. Сколько предметов всего?","en":f"There are {a} groups with {b} objects in each group. How many objects are there altogether?"}
    elif kind.startswith("div"):
        texts={"kk":f"{a} затты {b} тең топқа бөл. Әр топта неше зат болады?","ru":f"Раздели {a} предметов на {b} равные группы. Сколько предметов будет в каждой группе?","en":f"Divide {a} objects into {b} equal groups. How many objects will be in each group?"}
    else:
        expr=task.get("q","").split(" өрнегінің")[0]
        texts={"kk":f"{expr} өрнегінің мәнін тап.","ru":f"Найди значение выражения {expr}.","en":f"Find the value of the expression {expr}."}
    buttons={"kk":"🔊 СҰРАҚТЫ ҚАЗАҚША ОҚУ","ru":"🔊 ПРОЧИТАТЬ ПО-РУССКИ","en":"🔊 READ IN ENGLISH"}
    tips={"kk":"Жауапты төмендегі түрлі түсті батырмалардан таңда.","ru":"Выбери ответ с помощью цветных кнопок ниже.","en":"Choose the answer using the colorful buttons below."}
    return lang,texts[lang],buttons[lang],tips[lang]

def sen_prepare_speech(state):
    if not state:
        return "", "kk-KZ"
    task=None
    d=state.get("diag")
    if d and d.get("i",0)<len(d.get("tasks",[])):
        task=d["tasks"][d["i"]]
    elif state.get("practice") and state.get("pi",0)<len(state["practice"]):
        task=state["practice"][state["pi"]]
    if not task:
        return "", {"Қазақша":"kk-KZ","Русский":"ru-RU","English":"en-US"}.get(state.get("language"),"kk-KZ")
    short,text,_,_=sen_localized_task(task,state.get("language","Қазақша"))
    ending={"kk":" Жауап нұсқасын таңда.","ru":" Выбери вариант ответа.","en":" Choose an answer."}[short]
    return text+ending,{"kk":"kk-KZ","ru":"ru-RU","en":"en-US"}[short]

TTS_VOICES={"kk-KZ":"kk-KZ-AigulNeural","ru-RU":"ru-RU-SvetlanaNeural","en-US":"en-US-JennyNeural"}

async def create_tts_audio(text, language_code="kk-KZ"):
    if not str(text).strip(): return None,"<div class='warn'>Оқылатын мәтін табылмады.</div>"
    voice=TTS_VOICES.get(language_code,"kk-KZ-AigulNeural")
    key=hashlib.sha256(f"{voice}|{text}".encode("utf-8")).hexdigest()[:24]
    path=Path(tempfile.gettempdir())/f"aig_tts_{key}.mp3"
    try:
        if not path.exists():
            await edge_tts.Communicate(str(text),voice,rate="-12%",pitch="+0Hz").save(str(path))
        return str(path),"<div class='sen-good'>🔊 Дыбыс дайын және ойнатылып жатыр.</div>"
    except Exception:
        return None,"<div class='warn'>Дыбысты жасау үшін Colab интернеті қажет. Интернет байланысын тексеріп, батырманы қайта басыңыз.</div>"

async def sen_question_audio(state):
    text,code=sen_prepare_speech(state)
    return await create_tts_audio(text,code)

async def greeting_audio_file(name):
    student=str(name or "").strip()
    if not student: return None,"<div class='warn'>Алдымен оқушының аты-жөнін жазыңыз.</div>"
    text=f"Сәлем, {student}! AI-G ЖИ-ассистентіне қош келдің! Бүгінгі математикалық тапсырмаларыңа сәттілік тілеймін. Сенің қолыңнан келеді!"
    return await create_tts_audio(text,"kk-KZ")

def sen_task_html(task, number=None, total=None, state=None):
    kind=task.get("kind",""); left=int(task.get("left",0)); right=int(task.get("right",0))
    symbol="🐰"
    for key,val in [("apple","🍎"),("butterfly","🦋"),("balloon","🎈"),("fish","🐟"),("candy","🍬"),("bread","🥯"),("pencil","✏️")]:
        if key in kind: symbol=val
    if kind.startswith("add"):
        scene=f"<div>{sen_objects(symbol,left)}</div><b class='sen-sign'>＋</b><div>{sen_objects(symbol,right)}</div><b class='sen-sign'>＝ ?</b>"
    elif kind.startswith("sub"):
        scene=f"<div>{sen_objects(symbol,left-right)}{sen_objects(symbol,right,True)}</div><b class='sen-sign'>{left} − {right} ＝ ?</b>"
    elif kind.startswith("mul"):
        unit=right
        groups="".join(f"<span class='sen-group'>{sen_objects(symbol,unit)}</span>" for _ in range(left))
        scene=f"<div class='sen-groups'>{groups}</div><b class='sen-sign'>{left} × {right} ＝ ?</b>"
    elif kind.startswith("div"):
        groups="".join(f"<span class='sen-group'>{sen_objects(symbol,max(1,left//right))}</span>" for _ in range(right))
        scene=f"<div class='sen-groups'>{groups}</div><b class='sen-sign'>{left} ÷ {right} ＝ ?</b>"
    else:
        scene=f"<div class='sen-number'>{task['q'].split('өрнегінің')[0]}</div>"
    badge=f"<span class='count'>{number} / {total}</span>" if number else ""
    prefs=(state or {}).get("support",{}); language=(state or {}).get("language","Қазақша")
    lang_code,task_text,read_label,answer_tip=sen_localized_task(task,language)
    auto=""
    contrast="contrast" if prefs.get("contrast") else ""
    speech_text={"kk":task_text+" Жауап нұсқасын таңдаңыз.","ru":task_text+" Выберите вариант ответа.","en":task_text+" Choose an answer."}[lang_code]
    text_json=json.dumps(speech_text,ensure_ascii=False)
    page=f"""<!doctype html><html lang='{lang_code}'><head><meta charset='utf-8'><style>
    *{{box-sizing:border-box}}body{{margin:0;font-family:Arial,sans-serif;background:transparent;color:#172554}}.card{{position:relative;padding:18px;border-radius:24px;background:linear-gradient(145deg,#fff,#f0fdfa);border:3px solid #22d3ee;text-align:center;overflow:hidden}}.contrast{{background:#050816;color:#fff;border-color:#facc15}}.contrast h2,.contrast p{{color:#fff}}h2{{margin:8px 35px;color:#6d28d9;font-size:24px;line-height:1.35}}p{{font-weight:700}}.count{{position:absolute;right:10px;top:8px;background:#7c3aed;color:#fff;border-radius:99px;padding:6px 10px;font-weight:900}}.scene{{min-height:120px;padding:14px;border-radius:20px;background:linear-gradient(120deg,#fef3c7,#fce7f3,#cffafe);display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:10px}}.sen-item{{display:inline-block;font-size:34px;margin:2px;animation:bounce 1.2s infinite alternate}}.sen-leave{{animation:leave 2.1s infinite!important;opacity:.4}}.sen-sign{{font-size:34px;color:#be185d}}.sen-groups{{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}}.sen-group{{padding:6px;border:3px dashed #8b5cf6;border-radius:14px;background:#fff9}}.sen-number{{font-size:42px;font-weight:900;color:#0e7490}}.voice-note{{display:inline-block;padding:9px 15px;border-radius:99px;background:#e0f2fe;color:#075985;font-weight:bold}}@keyframes bounce{{to{{transform:translateY(-11px) rotate(4deg)}}}}@keyframes leave{{70%,100%{{transform:translateX(48px) translateY(-18px);opacity:.1}}}}</style></head><body><div class='card {contrast}'>{badge}<h2>{task_text}</h2><div class='voice-note'>🔊 {read_label}</div><div class='scene'>{scene}</div><p>{answer_tip}</p></div></body></html>"""
    encoded=base64.b64encode(page.encode("utf-8")).decode("ascii")
    return f"<iframe title='ЕББҚ математикалық тапсырма' src='data:text/html;base64,{encoded}' style='width:100%;height:355px;border:0;border-radius:24px' allow='autoplay'></iframe>"

