def sen_celebration_html(name="Батыр"):
    safe=json.dumps(str(name),ensure_ascii=False)
    page=f"""<!doctype html><html><head><meta charset='utf-8'><style>body{{margin:0;overflow:hidden;background:radial-gradient(circle,#312e81,#0f172a);font-family:Arial;color:white;text-align:center}}canvas{{position:absolute;inset:0}}.box{{position:relative;z-index:2;padding:35px 10px}}h1{{font-size:40px;text-shadow:0 0 18px #facc15;animation:pop .7s infinite alternate}}p{{font-size:21px;font-weight:bold}}button{{padding:13px 22px;border:0;border-radius:99px;background:linear-gradient(90deg,#f59e0b,#ec4899);color:white;font-weight:900;font-size:17px;cursor:pointer}}@keyframes pop{{to{{transform:scale(1.08)}}}}</style></head><body><canvas id='c'></canvas><div class='box'><h1>🎉 ЖАРАЙСЫҢ! 🎉</h1><p id='name'></p><p>Сен бүгін керемет еңбек еттің!</p><button onclick='sound()'>🔊 ҚҰТТЫҚТАУ ДЫБЫСЫН ҚОСУ</button></div><script>document.getElementById('name').innerText={safe}+' — нағыз математика жұлдызы!';let c=document.getElementById('c'),x=c.getContext('2d'),ps=[];function size(){{c.width=innerWidth;c.height=innerHeight}}size();onresize=size;function boom(){{let cx=Math.random()*c.width,cy=40+Math.random()*c.height*.55,cols=['#facc15','#22d3ee','#f472b6','#4ade80','#a78bfa'];for(let i=0;i<65;i++)ps.push({{x:cx,y:cy,vx:(Math.random()-.5)*7,vy:(Math.random()-.5)*7,a:1,col:cols[i%cols.length]}})}}setInterval(boom,700);function draw(){{x.fillStyle='#0f172a33';x.fillRect(0,0,c.width,c.height);ps.forEach(p=>{{p.x+=p.vx;p.y+=p.vy;p.vy+=.035;p.a-=.012;x.globalAlpha=Math.max(0,p.a);x.fillStyle=p.col;x.beginPath();x.arc(p.x,p.y,3,0,7);x.fill()}});ps=ps.filter(p=>p.a>0);x.globalAlpha=1;requestAnimationFrame(draw)}}draw();boom();function sound(){{let a=new (AudioContext||webkitAudioContext)(),notes=[523,659,784,1047];notes.forEach((f,i)=>{{let o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=f;o.type='triangle';g.gain.setValueAtTime(.001,a.currentTime+i*.16);g.gain.exponentialRampToValueAtTime(.22,a.currentTime+i*.16+.03);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+i*.16+.3);o.start(a.currentTime+i*.16);o.stop(a.currentTime+i*.16+.32)}})}}setTimeout(sound,500);</script></body></html>"""
    enc=base64.b64encode(page.encode()).decode()
    return f"<iframe title='Дыбысты отшашу құттықтауы' src='data:text/html;base64,{enc}' style='width:100%;height:330px;border:0;border-radius:24px' allow='autoplay'></iframe>"

def sen_submit_practice(answer,state):
    hidden=gr.update(visible=False)
    if not state or not state.get("practice"): return state,"<div class='sen-tip'>Алдымен диагностиканы аяқтаңыз.</div>","",gr.update(),gr.update(),hidden,hidden,hidden,""
    if answer is None: return state,"<div class='sen-tip'>Жауап нұсқасын таңдаңыз.</div>",sen_show_practice(state),gr.update(),gr.update(),gr.update(visible=True),hidden,hidden,""
    t=state["practice"][state["pi"]]
    if str(answer)!=t["a"]:
        state["tries"]=state.get("tries",0)+1
        idx=min(state["tries"]-1,len(t["steps"])-1)
        return state,f"<div class='sen-tip'>💛 Талпынысың жақсы! Дайын жауапты айтпаймыз.<br><b>Көмек:</b> {t['steps'][idx]}</div>",sen_task_html(t,state["pi"]+1,len(state["practice"]),state),gr.update(value=None),gr.update(),gr.update(visible=True),hidden,hidden,""
    state["correct"]+=1; state["pi"]+=1; state["tries"]=0
    if state["pi"]==3 and not state.get("continued"):
        state["paused"]=True
        ask="<div class='sen-level'><div class='sen-big'>😊</div><h2>Сен 3 тапсырманы орындадың!</h2><h3>Шаршадың ба, әлде жалғастырамыз ба?</h3><p>Демалуға да болады. Жалғастырсаң, тағы 3 қызықты тапсырма ашылады.</p></div>"
        return state,ask,"",hidden,hidden,hidden,gr.update(visible=True),gr.update(visible=True),""
    if state["pi"]>=len(state["practice"]):
        total=len(state["practice"]); return state,f"<div class='sen-good'><h2>🏆 Керемет жұмыс!</h2><p>{total} тапсырманың {state['correct']}-і дұрыс орындалды.</p><p>Бала суретпен санады, жауап таңдады және педагог-ассистент көмегін қолданды.</p></div>","",hidden,hidden,hidden,hidden,hidden,sen_celebration_html(state.get('name','Батыр'))
    n=state["practice"][state["pi"]]
    return state,"<div class='sen-good'>✨ Дұрыс! Келесі ойын-есепке өтеміз.</div>",sen_task_html(n,state["pi"]+1,len(state["practice"]),state),gr.update(choices=n["choices"],value=None,visible=True),gr.update(visible=True),gr.update(visible=True),hidden,hidden,""

def sen_continue_work(state):
    if not state or not state.get("paused"): return state,"<div class='sen-tip'>Алдымен алғашқы 3 тапсырманы орындаңыз.</div>","",gr.update(),gr.update(),gr.update(),gr.update(),gr.update(),""
    state["paused"]=False; state["continued"]=True; n=state["practice"][state["pi"]]
    return state,"<div class='sen-good'><h2>🚀 Тамаша! Тағы 3 қызықты тапсырма ашылды.</h2></div>",sen_task_html(n,state["pi"]+1,len(state["practice"]),state),gr.update(choices=n["choices"],value=None,visible=True),gr.update(visible=True),gr.update(visible=True),gr.update(visible=False),gr.update(visible=False),""

def sen_take_break(state):
    if state: state["paused"]=False
    name=(state or {}).get("name","Батыр")
    return state,"<div class='sen-good'><h2>💛 Жарайсың! Бүгінгі жұмысың аяқталды.</h2><p>Демалу — да оқу жоспарының маңызды бөлігі.</p></div>","",gr.update(visible=False),gr.update(visible=False),gr.update(visible=False),gr.update(visible=False),gr.update(visible=False),sen_celebration_html(name)

def month_calendar_html():
    cal=calendar.Calendar(firstweekday=0); weeks=cal.monthdayscalendar(now.year,now.month)
    rows="".join("<tr>"+"".join(f"<td class='today'>{d}</td>" if d==now.day else f"<td>{d or ''}</td>" for d in w)+"</tr>" for w in weeks)
    return f"<div class='calendar'><h3>📅 {MONTHS[now.month].capitalize()} {now.year}</h3><table><tr>{''.join(f'<th>{d}</th>' for d in DAYS)}</tr>{rows}</table></div>"

