SEN_SPEAK_JS = r"""async (text, lang) => {
  if (!text) return "<div class='sen-tip'>Алдымен тапсырманы ашыңыз.</div>";
  if (!('speechSynthesis' in window)) return "<div class='bad'>Бұл браузер дыбыстауды қолдамайды. Google Chrome қолданыңыз.</div>";
  const synth = window.speechSynthesis;
  let voices = synth.getVoices();
  if (!voices.length) {
    await new Promise(resolve => {
      let done = false;
      const finish = () => { if (!done) { done=true; resolve(); } };
      synth.onvoiceschanged = finish;
      setTimeout(finish, 1200);
    });
    voices = synth.getVoices();
  }
  const exact = String(lang).toLowerCase();
  const short = exact.split('-')[0];
  const voice = voices.find(v => v.lang.toLowerCase() === exact) || voices.find(v => v.lang.toLowerCase().startsWith(short));
  if (!voice) {
    const message = short === 'kk' ? 'Құрылғыда қазақша дауыс жоқ. Windows немесе Chrome баптауынан қазақша дауысты орнатыңыз.' : short === 'ru' ? 'На устройстве не установлен русский голос.' : 'No English voice is installed on this device.';
    return "<div class='warn'>🔇 " + message + "</div>";
  }
  synth.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = voice.lang; u.voice = voice; u.rate = 0.78; u.pitch = 1.02; u.volume = 1;
  synth.speak(u);
  const label = short === 'kk' ? 'Сұрақ қазақша оқылып жатыр…' : short === 'ru' ? 'Вопрос читается по-русски…' : 'The question is being read in English…';
  return "<div class='sen-good'>🔊 " + label + "</div>";
}"""

GREETING_JS = r"""async (name) => {
  const student = String(name || '').trim();
  if (!student) return "<div class='warn'>Алдымен оқушының аты-жөнін жазыңыз.</div>";
  if (!('speechSynthesis' in window)) return "<div class='bad'>Бұл браузер дыбыстауды қолдамайды. Google Chrome қолданыңыз.</div>";
  const synth = window.speechSynthesis;
  let voices = synth.getVoices();
  if (!voices.length) {
    await new Promise(resolve => {
      let finished=false;
      const done=()=>{if(!finished){finished=true;resolve();}};
      synth.onvoiceschanged=done; setTimeout(done,1200);
    });
    voices=synth.getVoices();
  }
  const voice=voices.find(v=>v.lang.toLowerCase()==='kk-kz') || voices.find(v=>v.lang.toLowerCase().startsWith('kk'));
  if (!voice) return "<div class='warn'>🔇 Құрылғыда қазақша дауыс табылмады. Windows тіл баптауынан қазақша дауысты орнатыңыз.</div>";
  synth.cancel();
  const text=`Сәлем, ${student}! AI-G ЖИ-ассистентіне қош келдің! Бүгінгі математикалық тапсырмаларыңа сәттілік тілеймін. Сенің қолыңнан келеді!`;
  const u=new SpeechSynthesisUtterance(text); u.lang=voice.lang;u.voice=voice;u.rate=.8;u.pitch=1.05;u.volume=1;
  const portrait=document.querySelector('.portrait'); if(portrait) portrait.classList.add('speaking');
  const stop=()=>{if(portrait)portrait.classList.remove('speaking');};u.onend=stop;u.onerror=stop;
  synth.speak(u);
  return "<div class='good'>👩‍🏫 AI-G сізбен сәлемдесіп жатыр…</div>";
}"""

PORTRAIT_ANIMATE_JS = """() => { const p=document.querySelector('.portrait'); if(p){p.classList.add('speaking');setTimeout(()=>p.classList.remove('speaking'),9000);} }"""

def append_math_symbol(value, symbol):
    if symbol=="ТАЗАЛАУ": return ""
    return str(value or "")+symbol

def math_keyboard(target):
    """Серверге сұраныс жібермейтін, қате шығармайтын мобильді формула пернетақтасы."""
    gr.Markdown("<small>⌨️ Формула пернетақтасы: таңбалар ретімен орналасқан. `x²` орнына `x2` деп жазсаңыз да жүйе таниды.</small>")
    rows=[["x","x²","x³","√(","π","×"],["÷","(",")",";","−","ТАЗАЛАУ"]]
    for symbols in rows:
        with gr.Row(equal_height=True):
            for symbol in symbols:
                b=gr.Button(symbol,size="sm",min_width=58,key=f"math_{id(target)}_{symbol}")
                js="(value) => ''" if symbol=="ТАЗАЛАУ" else f"(value) => String(value ?? '') + {json.dumps(symbol,ensure_ascii=False)}"
                b.click(fn=None,inputs=target,outputs=target,js=js,queue=False,show_progress="hidden")


